html:
{%- set qr = qr_data_uri(doc.epass_token) -%}
{%- set photo = photo_data_uri(doc.photo, 500) -%}
<style>
	.epass-page { width: 100%; text-align: center; font-family: Arial, Helvetica, sans-serif; color: #202124; }
	.epass { width: 430px; margin: 0 auto; border: 1px solid #cfd8d6; border-radius: 14px; overflow: hidden; text-align: left; background: #ffffff; }
	.epass-head { background: #2f7f73; color: #ffffff; padding: 22px 26px 18px 26px; }
	.epass-org { font-size: 11px; letter-spacing: 3px; text-transform: uppercase; color: #cfe8e3; }
	.epass-event { font-size: 20px; font-weight: bold; line-height: 1.3; margin-top: 6px; }
	.epass-tag { margin-top: 12px; }
	.epass-tag span { background: #ffffff; color: #2f7f73; font-size: 12px; font-weight: bold; letter-spacing: 3px; padding: 4px 14px; border-radius: 12px; }
	.epass-band { background: #def0ee; height: 6px; }
	.epass-id { width: 100%; border-collapse: collapse; margin: 0; }
	.epass-id td { vertical-align: top; padding: 22px 26px 8px 26px; }
	.epass-photo { width: 120px; height: 150px; border: 3px solid #def0ee; border-radius: 8px; background: #f1f3f4; }
	.epass-name { font-size: 21px; font-weight: bold; line-height: 1.25; margin-top: 2px; }
	.epass-desig { margin-top: 8px; }
	.epass-desig span { background: #def0ee; color: #1f5f55; font-size: 12px; font-weight: bold; padding: 3px 12px; border-radius: 12px; }
	.epass-school { margin-top: 12px; font-size: 13px; color: #3c4043; line-height: 1.45; }
	.epass-rows { width: 100%; border-collapse: collapse; margin: 6px 0 0 0; }
	.epass-rows td { padding: 8px 26px; font-size: 13px; border-top: 1px solid #e8eaed; }
	.epass-rows td.k { color: #5f6368; width: 38%; padding-right: 0; }
	.epass-rows td.v { font-weight: bold; text-align: right; }
	.epass-qr { text-align: center; padding: 14px 26px 6px 26px; border-top: 1px dashed #b6c4c1; margin-top: 8px; }
	.epass-qr img { width: 190px; height: 190px; border: 1px solid #dadce0; padding: 8px; border-radius: 8px; }
	.epass-scan { font-size: 12px; color: #5f6368; margin-top: 6px; }
	.epass-no { font-size: 12px; color: #202124; margin-top: 4px; letter-spacing: 1px; }
	.epass-venue td { padding-top: 10px; padding-bottom: 10px; }
	.epass-venue .addr { font-weight: bold; line-height: 1.45; margin-top: 3px; }
	.epass-venue .addr-line { line-height: 1.45; color: #3c4043; margin-top: 2px; }
	.epass-venue a { color: #2f7f73; font-size: 12px; }
	.epass-note { background: #f6f8f8; font-size: 10.5px; color: #5f6368; line-height: 1.5; padding: 12px 26px 14px 26px; margin-top: 12px; }
</style>

<div class="epass-page">
<div class="epass">
	<div class="epass-head">
		<div class="epass-org">Indian Talent Olympiad</div>
		<div class="epass-event">ITO Excellence Award Felicitation Ceremony 2026&ndash;27</div>
		<div class="epass-tag"><span>E-PASS</span></div>
	</div>
	<div class="epass-band"></div>

	<table class="epass-id">
		<tr>
			<td style="width:130px; padding-right:0;">
				{% if photo %}<img class="epass-photo" src="{{ photo }}">{% else %}<div class="epass-photo"></div>{% endif %}
			</td>
			<td>
				<div class="epass-name">{{ doc.full_name }}</div>
				<div class="epass-desig"><span>{{ doc.designation }}</span></div>
				<div class="epass-school">{{ doc.school_name }}</div>
			</td>
		</tr>
	</table>

	<table class="epass-rows">
		<tr><td class="k">School Code</td><td class="v">{{ doc.school_code }}</td></tr>
		<tr><td class="k">City</td><td class="v">{{ doc.school_city }}</td></tr>
		<tr><td class="k">State</td><td class="v">{{ doc.school_state }}</td></tr>
		<tr><td class="k">Date</td><td class="v">23 November 2026</td></tr>
		<tr><td class="k">Time</td><td class="v">10:00 AM &ndash; 1:00 PM</td></tr>
		<tr class="epass-venue"><td colspan="2"><span style="color:#5f6368">Venue</span>
			<div class="addr">Dr. B. R. Ambedkar Bhavana</div>
			<div class="addr-line">9c, 2nd A Cross Rd, Sector A, Yelahanka Satellite Town, Yelahanka New Town, Bengaluru, Karnataka 560064</div>
			<a href="https://maps.app.goo.gl/7Ca2HyThYC82fR9L8">Open in Google Maps</a></td></tr>
	</table>

	<div class="epass-qr">
		{% if qr %}<img src="{{ qr }}">{% endif %}
		<div class="epass-scan">Scan to verify this E-Pass</div>
	</div>

	<div class="epass-note">
		Entry is strictly for the invited individual. Accompanying persons, including family members, friends,
		colleagues or other guests, are not permitted. This pass is non-transferable and entry is subject to
		verification at the venue.
	</div>
</div>
</div>
